candidates.raw:
    adcs_mat3_t b, r, rt;

    /* Null check: any null -> ADCS_E_NULL, and if out exists write identity. */
    if ((pb == NULL) || (sb == NULL) || (pi == NULL) || (si == NULL)) {
        if (out != NULL) {
            *out = adcs_mat3_identity();
        }
        return ADCS_E_NULL;
    }
    if (out == NULL) {
        return ADCS_E_NULL;
    }

    /* Nonfinite component check: any -> ADCS_E_DEGENERATE, write identity. */
    if ((!adcs_is_finite_vec3(pb)) || (!adcs_is_finite_vec3(sb)) ||
        (!adcs_is_finite_vec3(pi)) || (!adcs_is_finite_vec3(si))) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    /* Build body and inertial triads; zero/collinear -> degenerate, write identity. */
    if ((triad_basis(pb, sb, &b) != ADCS_OK) || (triad_basis(pi, si, &r) != ADCS_OK)) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    /* c_bi = b * r^T  (inertial-to-body). */
    rt = adcs_mat3_transpose(&r);
    *out = adcs_mat3_mul(&b, &rt);
    return ADCS_OK;
}

